import{_ as t,o as a,c as i,aa as n}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/tickets/en_vykresy.png",r="/buildary-help-preview/media/en/tickets/en_vykres.png",o="/buildary-help-preview/media/en/tickets/en_mapa2.png",c="/buildary-help-preview/media/en/tickets/en_mapa.png",u=JSON.parse('{"title":"Drawings and Map","description":"","frontmatter":{"title":"Drawings and Map","wiki":"en:tickets:task_drawings"},"headers":[],"relativePath":"en/tickets/task_drawings.md","filePath":"en/tickets/task_drawings.md","lastUpdated":1794388980000}'),l={name:"en/tickets/task_drawings.md"};function d(p,e,g,h,w,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="drawings-and-map" tabindex="-1">Drawings and Map <a class="header-anchor" href="#drawings-and-map" aria-label="Permalink to &quot;Drawings and Map&quot;">​</a></h1><p>The <strong>Drawings and Map</strong> page is available by clicking it in the side navigation panel or from the Dashboard.</p><figure class="shot" style="--w:620px;"><img src="'+s+'" alt="Drawings and Map" width="600" loading="lazy"></figure><p>Drawings are available on a separate tab, as is the Map. The numbers next to the tab names indicate the number of tickets marked on them.</p><p>If the project is divided into parts and drawings have been uploaded for it (see the Project Parts and Drawings section), the required project part and/or drawing can be selected.</p><p>The number of recorded tickets is displayed for each drawing.</p><h2 id="drawings" tabindex="-1">Drawings <a class="header-anchor" href="#drawings" aria-label="Permalink to &quot;Drawings&quot;">​</a></h2><figure class="shot" style="--w:620px;"><img src="'+r+'" alt="Drawing with Markers" width="600" loading="lazy"></figure><p>Clicking a specific drawing opens it in a new window, where you can <strong>filter tickets according to your requirements</strong> - see the image.</p><p><strong>Hovering the mouse over a marker</strong> on the drawing displays basic information about the ticket <strong>with a link to Ticket Details</strong> for editing.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Double-clicking</strong> anywhere on the drawing opens the editing window for <strong>creating a new ticket</strong>, with a marker automatically placed at the location of the click on the respective drawing.</p></div><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><figure class="shot" style="--w:400px;"><img src="'+o+'" alt="Basic Map" width="380" loading="lazy"></figure><figure class="shot" style="--w:400px;"><img src="'+c+'" alt="Aerial Map" width="380" loading="lazy"></figure><p>The map opens with the view adjusted so that <strong>all ticket markers</strong> are visible. <strong>Clicking a marker</strong> opens basic information about the ticket <strong>with a link to Ticket Details</strong> for editing.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Double-clicking</strong> anywhere on the map opens the editing window for <strong>creating a new ticket</strong>, with the location automatically set to the point where you clicked.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In the bottom-right corner of the map, there is a switch icon for switching between the <strong>Basic and Aerial maps</strong>.</p></div>',17)])])}const _=t(l,[["render",d]]);export{u as __pageData,_ as default};
